package in.foodcart.data;
import in.foodcart.domain.OrderStatus; import in.foodcart.domain.OrderType; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Document("orders") @CompoundIndex(name="vendor_created",def="{'vendorId':1,'createdAt':-1}") @CompoundIndex(name="customer_created",def="{'customerId':1,'createdAt':-1}") public class OrderEntity { @Id public String id; public long orderNumber; public String vendorId,customerId,customerMobile,customerName,paymentMethod="CASH",rejectionReason,rejectionNote; /** "SUPPORT" when support cancelled and refunded it (SupportRefunds). */ public String cancelledBy; public OrderType type; /** The 30-minute slot the customer picked (start time). */ public Instant scheduledFor; public PaymentInfo payment; /** The receiver's code; whoever hands the order over must enter it (HandoverRules). */ public Handover handover; public OrderStatus status=OrderStatus.PLACED; public List<Item> items=new ArrayList<>(); public BigDecimal subtotal,total; /** Set when a weekly subscription placed this order (Subscriptions). */ public String subscriptionId; public Instant createdAt=Instant.now(),acceptedAt,preparingAt,readyAt,completedAt,rejectedAt,cancelledAt,noShowAt; /** CASH orders: when the stall took the money (at handover). */ public Instant cashCollectedAt; /** CASH orders whose GST is on a collection statement (VendorCollections). */ public String collectionNumber; public boolean cash(){return "CASH".equals(paymentMethod)&&payment==null;} /** The bill as charged (BillRules); null on orders from before pricing (Oct 11), whose total is the item total. */ public Bill bill; /** Tax invoice numbers, set at handover (InvoiceNumbers). */ public Invoice invoice; public static class Bill { public java.math.BigDecimal itemTotal,foodGst,platformFee,platformFeeGst,total; /** Rates in percent, as charged. */ public java.math.BigDecimal foodGstPercent,platformFeePercent,platformFeeGstPercent; } public static class Invoice { public String foodNumber,platformNumber; public Instant issuedAt; } public static class Item { public String menuItemId,name,portion="FULL",summary; public BigDecimal price,lineTotal; public int quantity; } }
